/**
 * Compiled WorldPack — agenda/scenario data for the v4 world layer.
 *
 * Regime *parameters* (drift/vol multipliers, transition tables) live in
 * world.ts (engine balance, like balance.ts). This pack carries the data that
 * external research feeds: the current agenda snapshot (topic weights) and
 * event-probability tilts per topic. Regenerated by
 * `npm run build:worldpack` (tools/build-worldpack.mjs) from
 * tools/data/raw/*.json — hand edits allowed, prefer updating raw data.
 */
import type { GameState, RegimeId } from './types';

export interface AgendaTopicDef {
  /** Display weight 0..1 for the topic chip (UI). */
  weight: number;
  /** eventId -> multiplier applied to the per-tick draw probability. */
  eventMults: Record<string, number>;
}

/** Per-asset regime overrides — replace the base regime multipliers. */
export interface RegimeMults {
  driftMult: number;
  volMult: number;
}

export interface ScenarioDef {
  id: string;
  /** Anchor year for display and timeline labels. */
  startYear: number;
  /**
   * Anchor month (1-12) for the calendar date — display-only, like startYear
   * (v7): the in-game clock is a pure derivation, never engine state.
   */
  startMonth: number;
  /** Initial world regime at game start. */
  worldRegime: RegimeId;
  /** Agenda override applied at game start (topicId -> weight). */
  agenda: Record<string, number>;
  /**
   * v8 — annual home-CPI overrides by countryId, applied ONLY while the arc
   * is live (beatCursor < beats.length): the authored era prices, after which
   * the residency catalog's current-era rates resume (a permanent override
   * would compound 1973 US CPI ×25 by year 50 — historically wrong).
   * Partial by design; unknown ids fall back to the catalog.
   */
  inflation?: Record<string, number>;
  /**
   * Scripted beats — deterministic, zero draws. `atTick` is months since
   * game start. Regime flips and news headlines fire exactly on schedule.
   */
  beats: ScenarioBeat[];
}

export interface ScenarioBeat {
  atTick: number;
  setRegime?: RegimeId;
  /** i18n key under scenarios.<id>.news.<n> — flavor headline for the log. */
  news?: number;
}

