export function scenarioDef(id: string): ScenarioDef {
  const def = WORLD_PACK.scenarios.find((s) => s.id === id);
  if (!def) throw new Error(`Unknown scenario: ${id}`);
  return def;
}

/** Calendar anchor for scenario-less runs — the pack's own era ('2026-10'). */
export const CURRENT_ERA_ANCHOR = { year: 2026, month: 10 };

/** The calendar anchor a run hangs from: its scenario, or the current era. */
export function anchorFor(scenarioId: string | null): { year: number; month: number } {
  if (scenarioId) {
    const def = WORLD_PACK.scenarios.find((s) => s.id === scenarioId);
    if (def) return { year: def.startYear, month: def.startMonth };
  }
  return { ...CURRENT_ERA_ANCHOR };
}

/**
 * The in-game calendar date after `tick` months (v7) — pure derivation, zero
 * draws, zero state writes: tick 0 IS the anchor month, Dec→Jan rolls the
 * year. world: null (legacy runs) hangs from the current era, same as fresh
 * scenario-less games. The optional tick serves history rows (entry ticks);
 * it defaults to the run's current tick.
 */
export function gameYearMonth(s: GameState, tick: number = s.tick): { year: number; month: number } {
  const a = s.world ? anchorFor(s.world.scenarioId) : anchorFor(null);
  const t = a.month - 1 + tick;
  return { year: a.year + Math.floor(t / 12), month: (t % 12) + 1 };
}
